CREATE TABLE public.periodo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    caja_id uuid NOT NULL,
    anio smallint NOT NULL,
    mes smallint NOT NULL,
    fecha_reunion date NOT NULL,
    estado public.periodo_estado DEFAULT 'ABIERTO'::public.periodo_estado NOT NULL,
    cerrado_at timestamp with time zone,
    cerrado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_periodo_cierre CHECK (((estado = 'CERRADO'::public.periodo_estado) = (cerrado_at IS NOT NULL))),
    CONSTRAINT ck_periodo_fecha CHECK (((EXTRACT(year FROM fecha_reunion) = (anio)::numeric) AND (EXTRACT(month FROM fecha_reunion) = (mes)::numeric))),
    CONSTRAINT periodo_anio_check CHECK (((anio >= 2020) AND (anio <= 2100))),
    CONSTRAINT periodo_mes_check CHECK (((mes >= 1) AND (mes <= 12)))
);

ALTER TABLE ONLY public.periodo FORCE ROW LEVEL SECURITY;


ALTER TABLE public.periodo OWNER TO postgres;

