    tasa_mensual numeric(6,4) NOT NULL,
    nro_cuotas smallint NOT NULL,
    metodo_amortizacion character varying(40) DEFAULT 'CAPITAL_FIJO_INTERES_SOBRE_SALDO'::character varying NOT NULL,
    fecha_desembolso date NOT NULL,
    fecha_primera_cuota date NOT NULL,
    estado public.prestamo_estado DEFAULT 'SOLICITADO'::public.prestamo_estado NOT NULL,
    proposito text,
    aprobado_por uuid,
    aprobado_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT ck_prestamo_fechas CHECK ((fecha_primera_cuota > fecha_desembolso)),
    CONSTRAINT prestamo_monto_principal_check CHECK ((monto_principal > (0)::numeric)),
    CONSTRAINT prestamo_nro_cuotas_check CHECK (((nro_cuotas >= 1) AND (nro_cuotas <= 60))),
    CONSTRAINT prestamo_tasa_mensual_check CHECK (((tasa_mensual >= (0)::numeric) AND (tasa_mensual <= (1)::numeric)))
);

