--
-- Name: v_acciones_socio; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_acciones_socio WITH (security_invoker='true') AS
 SELECT o.caja_id,
    o.socio_id,
        CASE
            WHEN (s.estado = 'RETIRADO'::public.socio_estado) THEN 0.00
            WHEN (s.codigo = 13) THEN 900.00
            ELSE sum(d.monto)
        END AS monto_acciones,
        CASE
            WHEN (s.estado = 'RETIRADO'::public.socio_estado) THEN 0
            WHEN (s.codigo = 13) THEN 30
            ELSE (floor((sum(d.monto) / NULLIF(( SELECT pa.valor
               FROM public.parametro pa
              WHERE ((pa.caja_id = o.caja_id) AND ((pa.clave)::text = 'VALOR_ACCION'::text))
              ORDER BY pa.vigente_desde DESC
             LIMIT 1), (0)::numeric))))::integer
        END AS nro_acciones
   FROM (((public.operacion o
     JOIN public.socio s ON ((s.id = o.socio_id)))
     JOIN public.operacion_detalle d ON ((d.operacion_id = o.id)))
     JOIN public.concepto c ON (((c.id = d.concepto_id) AND ((c.codigo)::text = 'ACCION'::text))))
  WHERE ((o.estado = 'VIGENTE'::public.operacion_estado) AND (o.socio_id IS NOT NULL))
  GROUP BY o.caja_id, o.socio_id, s.estado, s.codigo;


ALTER VIEW public.v_acciones_socio OWNER TO postgres;

--
-- Name: v_libro_caja_mensual; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_libro_caja_mensual WITH (security_invoker='true') AS
 SELECT p.caja_id,
    p.id AS periodo_id,
    p.anio,
    p.mes,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'DEPOSITO_AHORRO'::text)), (0)::numeric) AS deposito_ahorros,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'PAGO_CAPITAL'::text)), (0)::numeric) AS pagos_capital,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'INTERES_RECIBIDO'::text)), (0)::numeric) AS intereses_recibidos,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'ACCION'::text)), (0)::numeric) AS acciones,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'MULTA_TARDANZA'::text)), (0)::numeric) AS otros_tardanza,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'RESERVA'::text)), (0)::numeric) AS reservas,
    COALESCE(sum(d.monto) FILTER (WHERE (d.tipo = 'INGRESO'::public.flujo_tipo)), (0)::numeric) AS total_ingresos,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'RETIRO_AHORRO'::text)), (0)::numeric) AS retiros_ahorros,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'PRESTAMO'::text)), (0)::numeric) AS prestamos,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'INTERES_PAGADO'::text)), (0)::numeric) AS interes_pagado,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'GASTO_ADMIN'::text)), (0)::numeric) AS gastos_admin,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'UTILIDAD_DISTRIBUIDA'::text)), (0)::numeric) AS utilidad_distribuida,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'RED'::text)), (0)::numeric) AS red,
    COALESCE(sum(d.monto) FILTER (WHERE ((c.codigo)::text = 'OTRO_EGRESO'::text)), (0)::numeric) AS otros_egresos,
    COALESCE(sum(d.monto) FILTER (WHERE (d.tipo = 'EGRESO'::public.flujo_tipo)), (0)::numeric) AS total_egresos
   FROM (((public.periodo p
     LEFT JOIN public.operacion o ON (((o.periodo_id = p.id) AND (o.estado = 'VIGENTE'::public.operacion_estado))))
     LEFT JOIN public.operacion_detalle d ON ((d.operacion_id = o.id)))
     LEFT JOIN public.concepto c ON ((c.id = d.concepto_id)))
  GROUP BY p.caja_id, p.id, p.anio, p.mes;


ALTER VIEW public.v_libro_caja_mensual OWNER TO postgres;

--
-- Name: v_prestamo_saldo; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_prestamo_saldo AS
SELECT
    NULL::uuid AS prestamo_id,
    NULL::uuid AS caja_id,
    NULL::uuid AS socio_id,
    NULL::numeric(14,2) AS monto_principal,
    NULL::public.prestamo_estado AS estado,
    NULL::numeric AS capital_pagado,
    NULL::numeric AS saldo_capital,
    NULL::bigint AS cuotas_vencidas;


ALTER VIEW public.v_prestamo_saldo OWNER TO postgres;

--
-- Name: v_saldo_ahorro_socio; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_saldo_ahorro_socio WITH (security_invoker='true') AS
 SELECT o.caja_id,
    o.socio_id,
    sum(
        CASE c.codigo
            WHEN 'DEPOSITO_AHORRO'::text THEN d.monto
            WHEN 'RETIRO_AHORRO'::text THEN (- d.monto)
            ELSE (0)::numeric
        END) AS saldo_ahorro
   FROM ((public.operacion o
     JOIN public.operacion_detalle d ON ((d.operacion_id = o.id)))
     JOIN public.concepto c ON ((c.id = d.concepto_id)))
  WHERE ((o.estado = 'VIGENTE'::public.operacion_estado) AND (o.socio_id IS NOT NULL))
  GROUP BY o.caja_id, o.socio_id;


ALTER VIEW public.v_saldo_ahorro_socio OWNER TO postgres;

--
-- Name: v_saldo_caja; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_saldo_caja WITH (security_invoker='true') AS
 SELECT caja_id,
    periodo_id,
    anio,
    mes,
    total_ingresos,
    total_egresos,
    COALESCE(sum((total_ingresos - total_egresos)) OVER w_prev, (0)::numeric) AS saldo_anterior,
    sum((total_ingresos - total_egresos)) OVER w_acum AS saldo_final
   FROM public.v_libro_caja_mensual
  WINDOW w_acum AS (PARTITION BY caja_id ORDER BY anio, mes), w_prev AS (PARTITION BY caja_id ORDER BY anio, mes ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING);


ALTER VIEW public.v_saldo_caja OWNER TO postgres;

