--
-- Name: v_prestamo_saldo _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.v_prestamo_saldo WITH (security_invoker='true') AS
 SELECT p.id AS prestamo_id,
    p.caja_id,
    p.socio_id,
    p.monto_principal,
    p.estado,
    COALESCE(sum(c.capital_pagado), (0)::numeric) AS capital_pagado,
    (p.monto_principal - COALESCE(sum(c.capital_pagado), (0)::numeric)) AS saldo_capital,
    count(*) FILTER (WHERE (c.estado = 'VENCIDA'::public.cuota_estado)) AS cuotas_vencidas
   FROM (public.prestamo p
     LEFT JOIN public.cuota_prestamo c ON ((c.prestamo_id = p.id)))
  GROUP BY p.id;


