-- Name: arqueo_caja arqueo_caja_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY arqueo_caja_admin ON public.arqueo_caja USING ((EXISTS ( SELECT 1
   FROM public.periodo p
  WHERE ((p.id = arqueo_caja.periodo_id) AND (p.caja_id = public.app_caja_id()) AND public.app_es_admin())))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.periodo p
  WHERE ((p.id = arqueo_caja.periodo_id) AND (p.caja_id = public.app_caja_id()) AND public.app_es_admin()))));


